return items.map(item => {
  const o = item.json;
  const viral = Math.max(0, Math.min(100, Number(o.potencial_viral) || 0));
  const curiosidade = viral >= 85 ? 10 : viral >= 75 ? 7 : 5;
  const compartilhamento = viral >= 80 ? 10 : 7;
  const retencao = viral >= 80 ? 10 : 7;
  const score = Math.round((viral * 0.55) + (curiosidade * 2) + (compartilhamento * 2) + (retencao * 2));

  return {
    json: {
      ...o,
      viral_score: Math.min(100, score),
      componentes_viral: { viral, curiosidade, compartilhamento, retencao },
      etapa: 'VIRAL SCORE'
    }
  };
});

return items.map(item => {
  const o = item.json;
  const viral = Math.max(0, Math.min(100, Number(o.viral_score) || 0));
  const negocio = Math.max(0, Math.min(100, Number(o.potencial_negocio) || 0));
  const finalScore = Math.round((viral * 0.65) + (negocio * 0.35));

  return {
    json: {
      ...o,
      business_score: negocio,
      final_score: finalScore,
      prioridade: finalScore >= 85 ? 'ALTA' : finalScore >= 70 ? 'MEDIA' : 'BAIXA',
      etapa: 'BUSINESS SCORE'
    }
  };
});

const ordenados = [...items].sort((a, b) => Number(b.json.final_score || 0) - Number(a.json.final_score || 0));
if (!ordenados.length) return [];

const selecionado = ordenados[0].json;

return [{
  json: {
    ...selecionado,
    selecao: {
      quantidade_recebida: items.length,
      criterio: 'maior final_score',
      ranking: ordenados.map((x, i) => ({
        posicao: i + 1,
        id_oportunidade: x.json.id_oportunidade,
        final_score: x.json.final_score
      }))
    },
    fact_check_status: 'APROVADO_MOCK',
    aprovado_para_publicacao: true,
    fontes: [],
    observacao: 'MVP R$0: fact-check externo ainda não conectado. Esta aprovação permite apenas o teste da pipeline e da publicação MOCK.',
    etapa: 'FACT-CHECK'
  }
}];

return items.map(item => {
  const o = item.json;
  const hook = String(o.hook || '').trim();
  const relevancia = String(o.relevancia || '').trim();
  const angulo = String(o.angulo || '').trim();
  const roteiro = [
    `HOOK: ${hook}`,
    `CONTEXTO: ${relevancia}`,
    `DESENVOLVIMENTO: ${angulo}`,
    'VALOR: Explique o ponto principal de forma simples, objetiva e útil.',
    'CTA: Se isso foi útil, salve e compartilhe.'
  ].join('\n\n');

  return {
    json: {
      ...o,
      roteiro,
      formato: 'Vídeo curto vertical 9:16',
      duracao_alvo_segundos: 35,
      etapa: 'ROTEIRISTA'
    }
  };
});

return items.map(item => {
  const o = item.json;
  return {
    json: {
      ...o,
      direcao: {
        abertura: 'Começar com texto grande na tela e corte rápido.',
        cena_1: 'Apresentar visualmente o problema ou curiosidade.',
        cena_2: 'Mostrar a explicação principal com elementos visuais simples.',
        cena_3: 'Destacar a conclusão ou solução.',
        edicao: 'Cortes rápidos, legendas, zooms discretos e mudança visual a cada poucos segundos.',
        audio: 'Narração clara e música de fundo discreta.'
      },
      etapa: 'DIRETOR'
    }
  };
});

return items.map(item => {
  const o = item.json;
  const motivos = [];
  if (o.aprovado_para_publicacao !== true) motivos.push('Fact-check não aprovado.');
  if (!o.hook || String(o.hook).trim().length < 10) motivos.push('Hook ausente ou curto.');
  if (!o.roteiro || String(o.roteiro).length < 80) motivos.push('Roteiro insuficiente.');
  if (!o.direcao || !o.direcao.abertura) motivos.push('Direção visual incompleta.');

  const aprovado = motivos.length === 0;

  return {
    json: {
      ...o,
      qa_estrategico: {
        aprovado,
        motivos
      },
      etapa: 'QA ESTRATÉGICO',
      status: aprovado ? 'APROVADO' : 'BLOQUEADO'
    }
  };
});

return items.filter(item => item.json.qa_estrategico?.aprovado === true).map(item => ({
  json: {
    ...item.json,
    growth: {
      objetivo: 'Testar conteúdo, medir resultado e alimentar o próximo ciclo.',
      plataformas: ['TikTok', 'Instagram Reels', 'YouTube Shorts'],
      metricas: ['retenção', 'visualizações', 'compartilhamentos', 'salvamentos', 'comentários', 'conversão'],
      testes: ['Hook A', 'Hook B', 'CTA A'],
      regra_mvp: 'Após os primeiros 10 conteúdos, comparar resultados e ajustar os pesos do cérebro.'
    },
    etapa: 'GROWTH'
  }
}));

return items.map(item => {
  const d = item.json;
  const titulo = String(d.titulo || 'Conteúdo RUPTURA ONE').trim();
  const gancho = String(d.hook || d.gancho || `Você sabia que ${titulo.toLowerCase()}?`).trim();
  const publico = String(d.publico || 'público interessado no tema').trim();
  const angulo = String(d.angulo || 'solução prática').trim();

  return {
    json: {
      ...d,
      agente: 'GERADOR DE CONTEÚDO',
      conteudo: {
        titulo,
        gancho,
        desenvolvimento: `Apresente o problema com clareza, explique o ponto principal e entregue uma solução prática. Ângulo: ${angulo}.`,
        publico,
        cta: 'Siga para mais conteúdos e confira a próxima dica.'
      },
      status: 'gerado',
      etapa: 'GERADOR DE CONTEÚDO'
    }
  };
});

return items.map(item => {
  const d = item.json;
  const c = d.conteudo || {};
  const partes = [c.gancho, c.desenvolvimento, c.cta].filter(v => String(v || '').trim());
  const roteiroFinal = partes.join('\n\n');

  return {
    json: {
      ...d,
      roteiro_final: roteiroFinal,
      duracao_alvo_segundos: 35,
      formato: 'video_vertical_9x16',
      status: 'roteiro_pronto',
      etapa: 'ROTEIRO FINAL'
    }
  };
});

return items.map(item => {
  const d = item.json;
  const erros = [];
  if (!String(d.roteiro_final || '').trim()) erros.push('Roteiro vazio.');
  if (String(d.roteiro_final || '').length < 40) erros.push('Roteiro muito curto.');
  if (!String(d.titulo || '').trim()) erros.push('Título ausente.');
  if (!String(d.conteudo?.cta || '').trim()) erros.push('CTA ausente.');
  if (d.qa_estrategico?.aprovado !== true) erros.push('QA estratégico não aprovado.');

  const aprovado = erros.length === 0;

  return {
    json: {
      ...d,
      qa_conteudo: {
        aprovado,
        erros
      },
      status: aprovado ? 'APROVADO_PARA_PUBLICACAO' : 'BLOQUEADO',
      etapa: 'QA — CONTEÚDO'
    }
  };
});

return items.filter(item => item.json.qa_conteudo?.aprovado === true).map(item => {
  const d = item.json;
  return {
    json: {
      ...d,
      publicacao: {
        plataforma: 'TikTok',
        formato: '9:16',
        legenda: `${d.titulo || ''}\n\n${d.conteudo?.cta || ''}`.trim(),
        roteiro: d.roteiro_final || '',
        modo: 'MOCK_R$0',
        status: 'fila'
      },
      etapa: 'PACOTE DE PUBLICAÇÃO'
    }
  };
});

return items.map(item => {
  const d = item.json;
  return {
    json: {
      ...d,
      publicacao: {
        ...d.publicacao,
        modo: 'MOCK_R$0',
        publicado: true,
        resultado: 'SIMULADO_COM_SUCESSO',
        id_publicacao_mock: `MOCK-${Date.now()}`
      },
      etapa: 'PUBLICAÇÃO MOCK'
    }
  };
});

return items.map(item => {
  const d = item.json;
  return {
    json: {
      projeto: d.projeto || 'RUPTURA ONE',
      id_oportunidade: d.id_oportunidade,
      id_publicacao_mock: d.publicacao?.id_publicacao_mock || null,
      titulo: d.titulo,
      final_score: d.final_score,
      prioridade: d.prioridade,
      qa_estrategico: d.qa_estrategico,
      qa_conteudo: d.qa_conteudo,
      publicacao: d.publicacao,
      registro: {
        plataforma: 'TikTok',
        etapa: 'REGISTRO',
        modo: 'MOCK_R$0',
        timestamp: new Date().toISOString(),
        resultado: 'REGISTRADO_COM_SUCESSO'
      }
    }
  };
});
